// Runs during the AWS Amplify build (see amplify.yml) to save a copy of the
// Supabase keys into a file that ships with the built app.
//
// Why this exists: AWS Amplify's "Environment variables" console page only
// reliably feeds values into the BUILD step. This app also checks for these
// keys live, on the server, every time someone visits the site — and that
// live check was coming back empty even though the build has the values.
// This script writes the build-time values into a small generated file so
// the server can fall back to them if the live check fails.
//
// This file is regenerated on every build. Never edit it by hand, and never
// commit real key values here — src/integrations/supabase/runtime-env.generated.ts
// is gitignored precisely so real values never reach GitHub.

import { writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import path from "node:path";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const outFile = path.join(
  __dirname,
  "..",
  "src",
  "integrations",
  "supabase",
  "runtime-env.generated.ts",
);

const value = (key) => JSON.stringify(process.env[key] ?? "");

const contents = `// AUTO-GENERATED during build by scripts/generate-runtime-env.mjs.
// Do NOT edit this file by hand and do NOT commit real values into it —
// it is listed in .gitignore for that reason. Locally, it stays empty and
// the app reads straight from your .env file as before.
export const RUNTIME_ENV = {
  SUPABASE_URL: ${value("SUPABASE_URL")},
  SUPABASE_SERVICE_ROLE_KEY: ${value("SUPABASE_SERVICE_ROLE_KEY")},
  SUPABASE_PUBLISHABLE_KEY: ${value("SUPABASE_PUBLISHABLE_KEY")},
} as const;
`;

writeFileSync(outFile, contents);
console.log(`[generate-runtime-env] wrote ${outFile}`);
